-- Keep ten native acquisition lines on their own NPC while retaining real Player/owner text context.
-- Preserve every event/timer/repeat/group/BroadcastText,combat spell,phase,template and native kill-credit path.
SET @owner_voice_saved_concat=@@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=GREATEST(@@SESSION.group_concat_max_len,1048576);
START TRANSACTION;
